ns.Q[629]={n="The Vile Reef",nf="Le Récif infâme",l=37,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="pre",s={m=1434,x=32.3,y=27.7,n="Kin'weelay"},f={m=1434,x=32.3,y=27.7,n="Kin'weelay"},st="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",ft="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",o={{k="item",n="Tablet Shard",c=1,ins=false,unk=false,ns=false,outer=true,w={m=1434,x=24.8,y=23,n="Gri'lek the Wanderer"},src={{"Gri'lek the Wanderer",100}}}},oe="Bring a Tablet Shard to Kin'weelay at Grom'gol Base Camp.",of="Apporter un Fragment de tablette à Kin'weelay au Campement Grom'gol.",ne="Swim west from Grom'gol to the Vile Reef and dive to the tablet Gri'lek the Wanderer on the sea floor (24.8, 23): click it for the Tablet Shard. Saltscale murlocs guard the ruins, so clear a few first and watch your breath.",xp=2850,sh=true,req={{"Tablet Shard",1,"From the tablet Gri'lek the Wanderer, at the bottom of the Vile Reef (around 25, 23)"}}}
ns.Q[95748]={n="The Gurubashi Legends of Old",nf="Les anciennes légendes des Gurubashi",l=40,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="pre",p={629},s={m=1434,x=32.3,y=27.7,n="Kin'weelay"},f={m=1434,x=32.3,y=27.7,n="Kin'weelay"},st="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",ft="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",o={{k="item",n="The Third Troll Legend",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1434,x=22.9,y=12,n="Fall of Gurubashi"},src={{"Fall of Gurubashi",100}}}},oe="Use the hide and charcoal to make a rubbing of the Third Troll Legend tablet.",of="Utilisez la peau et le charbon pour créer une reproduction de la tablette de la troisième légende trolle.",ne="Go to the troll ruins of Zul'Kunda on the coast north of the Vile Reef (23, 12). Use Kin'weelay's hide and charcoal on the Fall of Gurubashi tablet. Bloodscalp trolls roam the ruins.",xp=3150,sh=true,req={{"The Third Troll Legend",1,"Rubbing of the tablet Fall of Gurubashi, in the troll ruins on the coast north of the Vile Reef (around 23, 12)"}}}
ns.Q[95770]={n="Locating the Lost City",nf="À la recherche de la cité perdue",l=40,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="pre",p={95748},s={m=1434,x=32.3,y=27.7,n="Kin'weelay"},f={m=1434,x=32.3,y=27.7,n="Kin'weelay"},st="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",ft="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",o={{k="event",n="Sunken Hollow cave",c=1,ins=false,unk=false,ns=true,w={m=1434,x=21.4,y=27.9,n="Sunken Hollow cave"}}},oe="Explore just west of the Vile Reef and find the cavern entrance, then report back to Kin'weelay.",of="Explorez le récif Infâme et trouvez l’entrée de la grotte.",ne="From Grom'gol, swim west past the Vile Reef and dive to the underwater cave of Sunken Hollow (about 21.5, 28), near the island with water elementals; a big tablet stands next to it. Reaching it completes the objective. Then go back to Kin'weelay.",xp=3150,sh=true}
ns.Q[95775]={n="The Drowned City",nf="La cité Submergée",l=40,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="pre",p={95770},s={m=1434,x=32.3,y=27.7,n="Kin'weelay"},f={m=1434,x=32.3,y=27.7,n="Kin'weelay"},st="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",ft="Kin'weelay, Grom'gol Base Camp, Stranglethorn Vale",o={{k="item",n="The First Tablet of I'lalai",c=1,ins=true,unk=false,ns=true},{k="item",n="The Second Tablet of I'lalai",c=1,ins=true,unk=false,ns=true},{k="item",n="The Third Tablet of I'lalai",c=1,ins=true,unk=false,ns=true},{k="item",n="The Fourth Tablet of I'lalai",c=1,ins=true,unk=false,ns=true}},oe="Use the hide and charcoal to make rubbings of the four Tablets of I'lalai in the Drowned City.",of="Utilisez la peau et le charbon pour créer des reproductions des tablettes trouvées dans la cité Submergée.",ne="Enter the Drowned City (underwater cave west of the Vile Reef, 21.4, 27.9). The four Tablets of I'lalai are in the ruins inside: at each one, use Kin'weelay's hide and charcoal to make a rubbing. Bring the four rubbings to Kin'weelay at Grom'gol.",xp=8450,sh=true,req={{"The First Tablet of I'lalai",1,"Rubbing of the first tablet, inside the Drowned City"},{"The Second Tablet of I'lalai",1,"Rubbing of the second tablet, inside the Drowned City"},{"The Third Tablet of I'lalai",1,"Rubbing of the third tablet, inside the Drowned City"},{"The Fourth Tablet of I'lalai",1,"Rubbing of the fourth tablet, inside the Drowned City"}}}
ns.Q[95776]={n="The Only Good Brinescale...",nf="Le seul bon Écaille-de-mer…",l=38,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="main",p={629,95748,95773,95770},s={m=1434,x=32.2,y=28.8,n="Commander Aggro'gosh"},f={m=1434,x=32.2,y=28.8,n="Commander Aggro'gosh"},st="Commander Aggro'gosh, Grom'gol Base Camp, Stranglethorn Vale",ft="Commander Aggro'gosh, Grom'gol Base Camp, Stranglethorn Vale",o={{k="kill",c=1,ins=false,unk=true,ns=false}},oe="Kill Var'Taka in the Drowned City.",of="Tuez Var’Taka dans la cité Submergée.",ne="Commander Aggro'gosh offers it once Enemies in the Water and Locating the Lost City (Kin'weelay) are both handed in.",ri={"Tidesoaked Leggings","Naga Priestess's Mantle"},rc=true,xp=9500,sh=true}
ns.Q[95773]={n="Enemies in the Water",nf="Des adversaires sous les flots",l=37,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="pre",p={95748},s={m=1434,x=32.2,y=28.8,n="Commander Aggro'gosh"},f={m=1434,x=32.2,y=28.8,n="Commander Aggro'gosh"},st="Commander Aggro'gosh, Grom'gol Base Camp, Stranglethorn Vale",ft="Commander Aggro'gosh, Grom'gol Base Camp, Stranglethorn Vale",o={{k="item",n="Brinescale Trident",c=10,ins=false,unk=false,ns=true,t={"Brinescale Skirmisher"},w={m=1434,x=22.5,y=25.6,n="Vile Reef"}}},oe="Gather 10 Brinescale Tridents from Brinescale Skirmishers.",of="Récupérez 10 tridents d’écaille-de-mer sur des tirailleurs écaille-de-mer.",ne="Kill Brinescale Skirmishers (naga) swimming around the sunken troll ruins of the Vile Reef, west of Grom'gol (about 22, 26), until you have 10 Brinescale Tridents. Watch your breath and come up between pulls.",xp=2850,sh=true,req={{"Brinescale Trident",10,"Dropped by Brinescale Skirmishers around the Vile Reef, west of Grom'gol (around 22, 26)"}}}
ns.Q[96774]={n="Ancient Gurubashi Idol",nf="L’idole des anciens Gurubashi",l=40,r=30,fa="Horde",d="TheDrownedCity",ds={"TheDrownedCity"},role="main",s={m=1412,x=32.5,y=20.6,n="Mazu'kon"},f={m=1412,x=32.6,y=20.6,n="Mazu'kon"},st="Mazu'kon, Mulgore",ft="Mazu'kon, Mulgore",o={{k="item",n="Ancient Gurubashi Idol",c=1,ins=true,unk=false,ns=true,src={{"Deathless Marrow"},{"Primeval Elemental"}}}},oe="Recover an Ancient Gurubashi Idol from the Drowned City.",of="Récupérez une idole antique des Gurubashi dans la cité Submergée.",ne="The idol drops at the flooded tomb by the western altar of the Drowned City (4th encounter: Deathless Marrow, then the Primeval Elemental); guides disagree on which of the two drops it. Take the quest from Mazu'kon in Mulgore before you go.",rw="Earthen Ring +300  •  Darkspear Trolls +150",xp=8800,sh=true,req={{"Ancient Gurubashi Idol",1,"From the most powerful priest in the Drowned City"}}}
ns.Q[95789]={n="Shady Saltseers",nf="Sel-augures véreux",l=40,r=34,fa="Both",d="TheDrownedCity",ds={"TheDrownedCity"},role="main",s={m=1434,x=26.9,y=77.2,n="Krazek"},f={m=1434,x=26.9,y=77.2,n="Krazek"},st="Krazek, Booty Bay, Stranglethorn Vale",ft="Krazek, Booty Bay, Stranglethorn Vale",o={{k="item",n="Voodoo-Infused Artifact",c=10,ins=true,unk=false}},oe="Collect 10 Voodoo-Infused Artifacts from the Saltseer pirates in the Drowned City.",of="Récupérez 10 artéfacts imprégnés de vaudou sur les pirates sel-augures de la cité Submergée.",ne="The Saltseer pirates inside the Drowned City (Captain Dreadrise's crew, around the central pool) drop the Voodoo-Infused Artifacts. You need 10 and it can take more than one run.",rw="1g  •  Booty Bay +100  •  Ratchet +50  •  Gadgetzan +50  •  Everlook +50",ri={"Rusted Troll War Belt","Saltseer's Helm"},rc=true,xp=10450,req={{"Voodoo-Infused Artifact",10,"Dropped by the Saltseer pirates in the Drowned City"}}}
ns.Q[95791]={n="The Saltseer Captain",nf="Le capitaine sel-augure",l=40,r=34,fa="Both",d="TheDrownedCity",ds={"TheDrownedCity"},role="main",s={m=1434,x=26.9,y=77.2,n="Krazek"},f={m=1434,x=26.9,y=77.2,n="Krazek"},st="Krazek, Booty Bay, Stranglethorn Vale",ft="Krazek, Booty Bay, Stranglethorn Vale",oe="Slay Captain Dreadrise and 3 Saltseer Coroners in the Drowned City.",of="Éliminez 3 légistes sel-augures ainsi que le capitaine Lèveffroi dans la cité Submergée.",rw="Booty Bay +100  •  Ratchet +50  •  Gadgetzan +50  •  Everlook +50",ri={"Mutinous Cuffs","South Seas Shroud"},rc=true,xp=10450}
ns.Q[3525]={n="Extinguishing the Idol",nf="L'extinction de l'idole",l=37,r=32,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="main",p={3523},s={i=1,n="Belnistrasz"},f={i=1,n="Belnistrasz's Brazier"},st="Belnistrasz, Razorfen Downs",ft="Belnistrasz's Brazier, Razorfen Downs",o={{k="event",ins=false,unk=false,ns=true}},oe="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs. Protect Belnistrasz while he performs the ritual to shut down the idol.",of="Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.\n\nProtéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole.",ne="Waves of undead attack during the ritual. Talk to the brazier near the idol afterwards to finish.",ri={"Dragonclaw Ring"},xp=10100}
ns.Q[3523]={n="Scourge of the Downs",nf="Le Fléau des Souilles",l=37,r=32,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",s={i=1,n="Belnistrasz"},f={i=1,n="Belnistrasz"},st="Belnistrasz, Razorfen Downs",ft="Belnistrasz, Razorfen Downs",o={{k="item",n="Belnistrasz's Oathstone",c=1,ins=false,unk=false,ns=true}},oe="If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.",of="Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée.",xp=675}
ns.Q[6626]={n="A Host of Evil",nf="L'hôte du mal",l=35,r=28,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="main",s={m=1413,x=49,y=94.8,n="Myriam Moonsinger"},f={m=1413,x=49,y=95,n="Myriam Moonsinger"},st="Myriam Moonsinger, Razorfen Downs thorn maze, The Barrens",ft="Myriam Moonsinger, Razorfen Downs thorn maze, The Barrens",o={{k="kill",n="Razorfen Battleguard",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1441,x=41.1,y=27.6,n="Razorfen Battleguard"},t={"Razorfen Battleguard"}},{k="kill",n="Razorfen Thornweaver",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1445,x=25,y=75.3,n="Razorfen Thornweaver"},t={"Razorfen Thornweaver"}},{k="kill",n="Death's Head Cultist",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1445,x=24.4,y=74.2,n="Death's Head Cultist"},t={"Death's Head Cultist"}}},oe="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.",of="Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge.",ne="These mobs are outside the instance, around the entrance.",rw="75s",xp=8200}
ns.Q[3341]={n="Bring the End",nf="L'anéantissement",l=42,r=37,fa="Horde",d="RazorfenDowns",ds={"RazorfenDowns"},role="main",s={m=1458,x=74,y=32.4,n="Andrew Brownell"},f={m=1458,x=74,y=33.3,n="Andrew Brownell"},st="Andrew Brownell, Undercity",ft="Andrew Brownell, Undercity",o={{k="item",n="Skull of the Coldbringer",c=1,ins=false,unk=true,ns=false,t={"Amnennar the Coldbringer"},src={{"Amnennar the Coldbringer",100}}}},oe="Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.",of="Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne.",rw="Undercity +150",ri={"Amberglow Talisman","Purified Ring","Vanquisher's Sword"},rc=true,xp=9050}
ns.Q[97196]={n="The Coldbringer's Eye",nf="L’Œil du Porte-froid",l=41,r=34,fa="Horde",d="RazorfenDowns",ds={"RazorfenDowns"},role="main",s={m=1412,x=34.4,y=22.8,n="Sutara Plainstalker"},f={m=1412,x=34.4,y=22.8,n="Sutara Plainstalker"},st="Sutara Plainstalker, Skywatcher Plateau, Mulgore",ft="Sutara Plainstalker, Skywatcher Plateau, Mulgore",oe="Recover The Coldbringer's Eye from Razorfen Downs.",of="Récupérez l’œil du Porte-froid dans les souilles de Tranchebauge.",rw="55s  •  Earthen Ring +300  •  Thunder Bluff +150",xp=8600,sh=true,req={{"The Coldbringer's Eye",1,"From Amnennar the Coldbringer, the last boss of Razorfen Downs"}}}
ns.Q[93604]={n="Agamaggan's Blood",l=45,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="main",p={92914,96010,96018,93016,93394,93341,93594,93404,93601},s={m=2652,x=72.6,y=31.4,n="Kog'thug the Brave"},f={m=2652,x=72.6,y=31.4,n="Kog'thug the Brave"},st="Kog'thug the Brave, Bristleback Retreat, Shen'dralas (72.6, 31.4)",ft="Kog'thug the Brave, Bristleback Retreat, Shen'dralas (72.6, 31.4)",o={{k="item",n="Virulent Blood of Agamaggan",c=1,ins=true,unk=false,src={{"Virulent Blood of Agamaggan",100}}}},oe="Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat.",ne="Click a Cauldron of Agamaggan's Blood to summon the Virulent Blood of Agamaggan and kill it for the blood. One cauldron is in the tent nearest the last boss (it may also be in other tents). Blood from Razorfen Kraul doesn't count.",rw="65s",xp=10200,sh=true,req={{"Virulent Blood of Agamaggan",1,"From the Virulent Blood of Agamaggan, which a Cauldron of Agamaggan's Blood summons in Razorfen Downs"}}}
ns.Q[92914]={n="Strange Pylons",nf="D’étranges pylônes",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",s={m=2652,x=43.6,y=34.2,n="Shen'dralar Pylon"},f={m=2652,x=35,y=46.4,n="Mordent Evenshade"},st="Shen'dralar Pylon, Shen'dralas (43.6, 34.2)",ft="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",o={{k="event",n="Shen'dralar Pylon (east)",c=1,ins=false,unk=false,w={m=2652,x=73,y=23,n="Shen'dralar Pylon"}},{k="event",n="Shen'dralar Pylon (south)",c=1,ins=false,unk=false,w={m=2652,x=47.6,y=76.7,n="Shen'dralar Pylon"}}},oe="Explore Shen'dralas in an effort to find other pylons like the one you found.",of="Explorez Shen’dralas pour trouver d’autres pylônes semblables à celui que vous avez découvert.",ne="The first pylon (43.6, 34.2) starts the quest. Find the other two: one to the east at about 73, 23, guarded by arcane elementals that can knock you off your mount, and one to the south at about 47.6, 76.7, inside the big Shen'dralas temple, watched by Pylon Protectors. Then go to Mordent Evenshade (35, 46).",xp=3600}
ns.Q[96010]={n="Fragments of the Pylons",l=41,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={92914},s={m=2652,x=35,y=46.4,n="Mordent Evenshade"},f={m=2652,x=35,y=46.4,n="Mordent Evenshade"},st="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",ft="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",o={{k="item",n="Pylon Fragment",c=1,ins=false,unk=false,w={m=1443,x=66,y=80,n="Magram Village"}},{k="item",n="Pylon Shard",c=1,ins=false,unk=false,w={m=1443,x=40.5,y=95.5,n="Gelkis Village"}}},oe="Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade.",ne="Each centaur village of south Desolace guards one pylon piece: Magram Village (Khan Jehn's camp, about 66, 80) and Gelkis Village (Khan Shaka's camp, about 40, 95). Without reputation both camps attack you, so fight your way in and loot the piece in each. Which village holds the Fragment and which the Shard is not known. Then go back to Mordent Evenshade.",xp=2450,req={{"Pylon Fragment",1,"Guarded in one of the centaur villages (Magram or Gelkis), Desolace"},{"Pylon Shard",1,"Guarded in the other centaur village (Magram or Gelkis), Desolace"}}}
ns.Q[96018]={n="Powering the Pylons",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={96010},s={m=2652,x=35,y=46.4,n="Mordent Evenshade"},f={m=2652,x=35,y=46.4,n="Mordent Evenshade"},st="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",ft="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",o={{k="object",n="Western pylon repaired",c=1,ins=false,unk=false,w={m=2652,x=43.6,y=34.2,n="Shen'dralar Pylon"}},{k="object",n="Eastern pylon repaired",c=1,ins=false,unk=false,w={m=2652,x=73,y=24,n="Shen'dralar Pylon"}}},oe="Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals, then empower the pylons and return to Mordent Evenshade.",xp=3600,ne="1) Top floor of the big temple in Shen'dralas (45.9, 78.2), beside Historian Biraxas: take the Mana Sieve. 2) With it in your bags, gather mana from the Unstable Mana Rifts (the floating sparks of mana all along the road north) until you have 8. 3) Use the other quest item with 4 mana on each pylon (Decrepit Pylon Protectors guard them): pylons at 43.6, 34.2 and 73, 24. Then back to Mordent Evenshade."}
ns.Q[93016]={n="A Brief History Lesson",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={96018},s={m=2652,x=35,y=46.4,n="Mordent Evenshade"},f={m=2652,x=35,y=46.4,n="Mordent Evenshade"},st="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",ft="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",oe="Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired.",ne="Only a talk: speak with Mordent Evenshade at Evenshade's Overlook (35, 46). He tells you about the pylons, then offers Meeting the Magister.",xp=360}
ns.Q[93394]={n="Meeting the Magister",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={93016},s={m=2652,x=35,y=46.4,n="Mordent Evenshade"},f={m=2652,x=47.2,y=75.8,n="Magister Kirandis"},st="Mordent Evenshade, Evenshade's Overlook, Shen'dralas (35.0, 46.4)",ft="Magister Kirandis, in the temple of Shen'dralas (47.2, 75.8)",oe="Locate Magister Kirandis inside the temple of Shen'dralas.",ne="Magister Kirandis is inside the big Shen'dralas temple, at about 47, 75. Talking to him ends the quest and opens the other Shen'dralas quests, Mithera's included.",xp=360}
ns.Q[93341]={n="Forlorn Gardens",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={93394},s={m=2652,x=52.8,y=76,n="Mithera"},f={m=2652,x=52.8,y=76,n="Mithera"},st="Mithera, by the Forlorn Gardens, Shen'dralas (52.8, 76.0)",ft="Mithera, by the Forlorn Gardens, Shen'dralas (52.8, 76.0)",o={{k="event",n="Forlorn Gardens shrine",c=1,ins=false,unk=false,w={m=2652,x=70.3,y=79.7,n="Forlorn Gardens shrine"}}},oe="Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple.",ne="Go south-east to the Forlorn Gardens (about 70, 80) and find the small shrine with an enchanted pedestal: the necklace that belongs on it is gone. Then go back to Mithera by the temple (53, 76). Her next quest, Word of the Woods, opens after this one.",xp=1800}
ns.Q[93594]={n="Word of the Woods",l=43,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={93341},s={m=2652,x=52.8,y=76,n="Mithera"},f={m=2652,x=69.7,y=71.8,n="Woodwyrd"},st="Mithera, by the Forlorn Gardens, Shen'dralas (52.8, 76.0)",ft="Woodwyrd, Forlorn Gardens, Shen'dralas (69.7, 71.8)",oe="Find Woodwyrd in the Forlorn Gardens at Shen'dralas.",ne="Mithera only sends you on: walk east to Woodwyrd, a treant in the Forlorn Gardens (about 70, 72), and talk to him to hand in. No fight. He then offers Rot and Regret.",xp=360}
ns.Q[93404]={n="Rot and Regret",l=49,r=35,fa="Both",d="Maraudon",ds={"RazorfenDowns","Maraudon"},role="main",p={93594},s={m=2652,x=69.7,y=71.8,n="Woodwyrd"},f={m=2652,x=69.7,y=71.8,n="Woodwyrd"},st="Woodwyrd, Forlorn Gardens, Shen'dralas (69.7, 71.8)",ft="Woodwyrd, Forlorn Gardens, Shen'dralas (69.7, 71.8)",o={{k="item",n="Vial of Earth Song Water",c=1,ins=true,unk=false}},oe="Venture to Maraudon and recover a Vial of Earth Song Water, then use it to put out Woodwyrd's flame at the Forlorn Gardens.",ne="In Maraudon, go down to Earth Song Falls and click the small geyser in the pools where Rotgrip swims to fill the vial. Back at the Forlorn Gardens, use the vial on the burning tree next to Woodwyrd, not on Woodwyrd himself. Afterwards Woodwyrd sends you to the Bristleback Retreat (Passing the Blame), which leads to Agamaggan's Blood in Razorfen Downs.",rw="Choose: Overgrown Cuffs or Thornplated Cord\n11,100 XP",ri={"Overgrown Cuffs","Thornplated Cord"},rc=true,xp=11100,req={{"Vial of Earth Song Water",1,"From the small geyser in the pools Rotgrip swims around in, Maraudon"}},use={258296}}
ns.Q[93601]={n="Passing the Blame",l=45,r=35,fa="Both",d="RazorfenDowns",ds={"RazorfenDowns"},role="pre",p={93404},s={m=2652,x=69.7,y=71.8,n="Woodwyrd"},f={m=2652,x=72.6,y=31.4,n="Kog'thug the Brave"},st="Woodwyrd, Forlorn Gardens, Shen'dralas (69.7, 71.8)",ft="Kog'thug the Brave, Bristleback Retreat, Shen'dralas (72.6, 31.4)",oe="Seek out a quilboar of significance at the Bristleback Retreat.",ne="Go north through the Valley of Bones to the Bristleback Retreat (72.6, 31.4) and talk to Kog'thug the Brave. He offers Agamaggan's Blood, for Razorfen Downs.",xp=390}
ns.Q[2202]={n="Uldaman Reagent Run",nf="Rechercher les composants à Uldaman",l=42,r=36,fa="Horde",d="Uldaman",ds={"Uldaman"},role="main",p={2258},s={m=1418,x=2.4,y=46,n="Jarkal Mossmeld"},f={m=1418,x=2.4,y=46.1,n="Jarkal Mossmeld"},st="Jarkal Mossmeld, Kargath, Badlands",ft="Jarkal Mossmeld, Kargath, Badlands",o={{k="item",n="Magenta Fungus Cap",c=12,ins=false,unk=false,ns=false,outer=true,w={m=1418,x=41,y=15,n="Magenta Cap Clusters"},src={{"Magenta Cap Clusters",100},{"Magenta Cap Clusters",100},{"Mound of Dirt",50}}}},oe="Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",of="Apporter 12 Champignons magenta à Jarkal Mossmeld à Kargath.",rw="55s",ri={"Restorative Potion"},xp=6750,req={{"Magenta Fungus Cap",1,"Mushrooms near the fires, mostly outside the instance in the Uldaman excavation"}}}
