ns.Q[3802]={n="Dark Iron Legacy",nf="Héritage Sombrefer",l=52,r=48,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={3801},s={m=1428,x=29,y=28.9,n="Franclorn Forgewright"},f={m=1428,x=28.8,y=28.4,n="Monument of Franclorn Forgewright"},st="Franclorn Forgewright, Blackrock Mountain",ft="Monument of Franclorn Forgewright, Blackrock Mountain",o={{k="item",n="Ironfel",c=1,ins=false,unk=true,ns=false,t={"Fineous Darkvire"},src={{"Fineous Darkvire",100}}}},oe="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.",of="Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright.",ne="Speak to Franclorn's ghost while dead. Kill Fineous Darkvire for Ironfel and place it on Franclorn's monument by the Ring of Law. The Shadowforge Key opens shortcuts inside BRD.",ri={"Shadowforge Key"},xp=9450,sh=true}
