ns.Q[4083]={n="The Spectral Chalice",nf="Le Calice spectral",l=55,r=40,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",s={i=1,n="Spectral Chalice"},f={i=1,n="Spectral Chalice"},st="Spectral Chalice, Blackrock Depths",ft="Spectral Chalice, Blackrock Depths",o={{k="item",n="Star Ruby",c=2,ins=false,unk=false,ns=true},{k="item",n="Gold Bar",c=20,ins=false,unk=false,ns=true},{k="item",n="Truesilver Bar",c=10,ins=false,unk=false,ns=true}},oe="Bring Gloom'rel 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars, then place them in the Spectral Chalice in the Summoners' Tomb.",of="Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant.",ne="Mining 230. Talk to Gloom'rel before the Seven fight; give the Spectral Chalice 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars to learn Smelt Dark Iron. Bring them with you: Star Rubies come from Mithril, Truesilver and Thorium veins (or as rare drops), Gold and Truesilver Bars only from random chests, so smelt them or buy them at the Auction House.",xp=5650,sh=true,prof="MINING"}
