ns.Q[3907]={n="Disharmony of Fire",nf="Discordance des flammes",l=56,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={3906},s={m=1418,x=3.4,y=48.2,n="Thunderheart"},f={m=1418,x=3.3,y=48.3,n="Thunderheart"},st="Thunderheart, Kargath, Badlands",ft="Thunderheart, Kargath, Badlands",o={{k="kill",n="Lord Incendius",c=1,ins=false,unk=true,ns=false,t={"Lord Incendius"}},{k="item",n="Tablet of Kurniya",c=1,ins=false,unk=true,ns=false,t={"Lord Incendius"},src={{"Lord Incendius",100}}}},oe="Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",of="Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart.",ne="Kill Lord Incendius at the Black Anvil inside BRD and bring back the Tablet of Kurniya.",ri={"Crypt Demon Bracers","Sunborne Cape","Nightfall Gloves","Stalwart Clutch"},rc=true,xp=13500,sh=true}
ns.Q[3906]={n="Disharmony of Flame",nf="Discordance des flammes",l=52,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",s={m=1418,x=3.4,y=48.2,n="Thunderheart"},f={m=1418,x=3.3,y=48.3,n="Thunderheart"},st="Thunderheart, Badlands",ft="Thunderheart, Badlands",o={{k="kill",n="Overmaster Pyron",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1429,x=58.1,y=20.9,n="Overmaster Pyron"},t={"Overmaster Pyron"}}},oe="Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.",of="Partir pour la carrière dans le mont Rochenoire et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie.",xp=5100,sh=true}
ns.Q[7201]={n="The Last Element",nf="Le dernier élément",l=54,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={3906},s={m=1418,x=3,y=47.6,n="Shadowmage Vivian Lagrave"},f={m=1418,x=2.9,y=47.8,n="Shadowmage Vivian Lagrave"},st="Shadowmage Vivian Lagrave, Kargath, Badlands",ft="Shadowmage Vivian Lagrave, Kargath, Badlands",o={{k="item",n="Essence of the Elements",c=10,ins=false,unk=false,ns=false,outer=false,w={m=1427,x=35.9,y=55.7,n="Scald"},t={"Scald","Warbringer Construct","Ragereaver Golem"},src={{"Scald",100},{"Warbringer Construct",80},{"Ragereaver Golem",80}}}},oe="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.",of="Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires.",ne="Essence of the Elements drops from BRD elementals and golems.",rw="2g 45s",ri={"Lagrave's Seal"},xp=10100,sh=true}
ns.Q[4063]={n="The Rise of the Machines",nf="La révolte des machines",l=58,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={4061,4062},s={m=1418,x=25.8,y=45,n="Lotwil Veriatus"},f={m=1418,x=25.9,y=44.9,n="Lotwil Veriatus"},st="Lotwil Veriatus, Badlands",ft="Lotwil Veriatus, Badlands",o={{k="item",n="Head of Argelmach",c=1,ins=false,unk=true,ns=false,t={"Golem Lord Argelmach"},src={{"Golem Lord Argelmach",100}}},{k="item",n="Intact Elemental Core",c=10,ins=false,unk=true,ns=false,t={"Warbringer Construct","Ragereaver Golem","Wrath Hammer Construct"},src={{"Warbringer Construct",80},{"Ragereaver Golem",80},{"Wrath Hammer Construct",80}}}},oe="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach.",of="Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.",ne="Kill Golem Lord Argelmach for his head and collect 10 Intact Elemental Cores from the constructs guarding him.",ri={"Azure Moon Amice","Raincaster Drape","Basaltscale Armor","Lavaplate Gauntlets"},rc=true,xp=12400,sh=true}
ns.Q[4061]={n="The Rise of the Machines",nf="La révolte des machines",l=54,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",s={m=1418,x=3,y=47.8,n="Hierophant Theodora Mulvadania"},f={m=1418,x=3,y=47.9,n="Hierophant Theodora Mulvadania"},st="Hierophant Theodora Mulvadania, Badlands",ft="Hierophant Theodora Mulvadania, Badlands",o={{k="item",n="Fractured Elemental Shard",c=10,ins=false,unk=false,ns=false,outer=false,w={m=1428,x=41.1,y=43.5,n="Greater Obsidian Elemental"},t={"Greater Obsidian Elemental","War Reaver","Malfunctioning Reaver"},src={{"Greater Obsidian Elemental",50},{"War Reaver",50},{"Malfunctioning Reaver",50}}}},oe="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.",of="S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.\n\nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments.",xp=5450,sh=true}
ns.Q[4062]={n="The Rise of the Machines",nf="La révolte des machines",l=54,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={4061},s={m=1418,x=3,y=47.8,n="Hierophant Theodora Mulvadania"},f={m=1418,x=25.9,y=44.9,n="Lotwil Veriatus"},st="Hierophant Theodora Mulvadania, Badlands",ft="Lotwil Veriatus",o={{k="item",n="Elemental Shard Sample",c=1,ins=false,unk=false,ns=true}},oe="Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east.",of="Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus.\n\nTheodora vous a dit qu'il se trouvait au camp à l'est.",xp=1350,sh=false}
ns.Q[4132]={n="Operation: Death to Angerforge",nf="Opération : Mort à Forgehargne",l=58,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={4081,4082,4122,4121},s={m=1418,x=5.8,y=47.4,n="Warlord Goretooth"},f={m=1418,x=5.8,y=47.5,n="Warlord Goretooth"},st="Warlord Goretooth, Kargath, Badlands",ft="Warlord Goretooth, Kargath, Badlands",o={{k="kill",n="General Angerforge",c=1,ins=false,unk=true,ns=false,t={"General Angerforge"}}},oe="Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.",of="Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth.",ne="Needs both KILL ON SIGHT quests and the Grark Lorkrub escort first.",ri={"Conqueror's Medallion"},xp=15500,sh=true}
ns.Q[4081]={n="KILL ON SIGHT: Dark Iron Dwarves",nf="TUER A VUE : nains Sombrefer",l=52,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",s={m=1418,x=3.8,y=47.5,n="WANTED"},f={m=1418,x=5.8,y=47.5,n="Warlord Goretooth"},st="Wanted Poster, Kargath, Badlands",ft="Warlord Goretooth, Kargath, Badlands",o={{k="kill",n="Anvilrage Guardsman",c=15,ins=false,unk=true,ns=false,t={"Anvilrage Guardsman"}},{k="kill",n="Anvilrage Warden",c=10,ins=false,unk=false,ns=false,outer=true,w={m=1427,x=30.9,y=83.2,n="Anvilrage Warden"},t={"Anvilrage Warden"}},{k="kill",n="Anvilrage Footman",c=5,ins=false,unk=true,ns=false,t={"Anvilrage Footman"}}},oe="Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.",of="Pénétrer dans les Profondeurs de Rochenoire et tuer les vils agresseurs !\n\nLe chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie.",xp=9950,sh=true,so="WANTED poster",soh="On the wall in Kargath, Badlands"}
ns.Q[4082]={n="KILL ON SIGHT: High Ranking Dark Iron Officials",nf="TUER A VUE : Officiers de haut rang Sombrefer",l=54,r=50,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={4081},s={m=1418,x=4,y=46.8,n="KILL ON SIGHT"},f={m=1418,x=5.8,y=47.5,n="Warlord Goretooth"},st="Wanted Poster, Kargath, Badlands",ft="Warlord Goretooth, Kargath, Badlands",o={{k="kill",n="Anvilrage Medic",c=10,ins=false,unk=true,ns=false,t={"Anvilrage Medic"}},{k="kill",n="Anvilrage Soldier",c=10,ins=false,unk=true,ns=false,t={"Anvilrage Soldier"}},{k="kill",n="Anvilrage Officer",c=10,ins=false,unk=true,ns=false,t={"Anvilrage Officer"}}},oe="Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.",of="Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs !\n\nLe Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie.",xp=10650,sh=true,so="KILL ON SIGHT poster",soh="On the wall in Kargath, Badlands"}
ns.Q[4122]={n="Grark Lorkrub",l=58,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={4082,4081},s={m=1418,x=5.8,y=47.4,n="Lexlort"},f={m=1428,x=40.2,y=34.2,n="Grark Lorkrub"},st="Lexlort, Badlands",ft="Grark Lorkrub, Burning Steppes",oe="Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.",of="Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock.\n\nUne fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde.",xp=6200,sh=false}
ns.Q[4121]={n="Precarious Predicament",nf="Situation précaire",l=58,r=52,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={4122},s={m=1428,x=40,y=34.6,n="Grark Lorkrub"},f={m=1418,x=5.9,y=47.7,n="Lexlort"},st="Grark Lorkrub, Burning Steppes",ft="Lexlort, Badlands",o={{k="item",n="Thorium Shackles",c=1,ins=false,unk=false,ns=true},{k="event",ins=false,unk=false,ns=true}},oe="Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort.",of="Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Blackrock, jusqu'à la gorge des Vents brûlants.\n\nRappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.\n\nOn vous demandera également de remettre vos chaînes en thorium à Lexlort.",xp=7750,sh=false}
ns.Q[4024]={n="A Taste of Flame",nf="Un goût de flammes",l=58,r=52,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={4023},s={m=1428,x=94.8,y=31.6,n="Cyrus Therepentous"},f={m=1428,x=95,y=31.5,n="Cyrus Therepentous"},st="Cyrus Therepentous, Burning Steppes",ft="Cyrus Therepentous, Burning Steppes",o={{k="item",n="Encased Fiery Essence",c=1,ins=false,unk=false,ns=true}},oe="Travel to Blackrock Depths and slay Bael'Gar. Use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous.",of="Partir pour les Profondeurs de Rochenoire et tuer Bael'Gar.\n\nVous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente.\n\nApporter l'Essence ardente recouverte à Cyrus Therepentous.",ne="Show Cyrus a Black Dragonflight Molt first (A Taste of Flame, or kill the drake he summons). Then kill Bael'Gar and use the Altered Black Dragonflight Molt on his remains to collect the Encased Fiery Essence.",ri={"Shaleskin Cape","Wyrmhide Spaulders","Valconian Sash"},rc=true,xp=11450,sh=false}
ns.Q[3441]={n="Divine Retribution",l=48,r=40,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",s={m=1427,x=39.1,y=39,n="Velarok Windblade"},f={m=1427,x=39.1,y=39,n="Velarok Windblade"},o={{k="kill",n="Velarok Windblade",ins=false,unk=false,ns=false,outer=false,w={m=1427,x=39.1,y=39,n="Velarok Windblade"},t={"Velarok Windblade"}}},xp=440}
ns.Q[4022]={n="A Taste of Flame",l=54,r=52,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",s={m=1428,x=95,y=31.5,n="Cyrus Therepentous"},f={m=1428,x=95,y=31.5,n="Cyrus Therepentous"},o={{k="item",n="Black Dragonflight Molt",c=1,ins=false,unk=false,ns=false,outer=true,w={m=1427,x=37.2,y=62,n="Heavy War Golem"},t={"Frenzied Black Drake","Dark Iron Taskmaster","Heavy War Golem"},src={{"Frenzied Black Drake",96.4},{"Dark Iron Taskmaster",0},{"Heavy War Golem",0}}},{k="kill",n="Cyrus Therepentous",ins=false,unk=false,ns=false,outer=false,w={m=2548,x=23.9,y=36.5,n="Cyrus Therepentous"},t={"Cyrus Therepentous"}}},xp=5450}
ns.Q[4003]={n="The Royal Rescue",nf="Un sauvetage royal",l=59,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={3906,3981,3982,4001,4002},s={m=1454,x=32,y=37.8,n="Thrall"},f={i=1,n="Princess Moira Bronzebeard"},st="Thrall, Grommash Hold, Orgrimmar",ft="Princess Moira Bronzebeard, Blackrock Depths",o={{k="kill",n="Emperor Dagran Thaurissan",c=1,ins=false,unk=true,ns=false,t={"Emperor Dagran Thaurissan"}}},oe="Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.",of="Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique.",ne="Keep Princess Moira alive and speak to her after Emperor Thaurissan dies. Her The Princess Saved? sends you back to Thrall for the reward.",rw="2g 70s",ri={"Thrall's Resolve","Eye of Orgrimmar"},rc=true,xp=16100,sh=true}
ns.Q[3981]={n="Commander Gor'shak",nf="Le commandant Gor'shak",l=52,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={3906},s={m=1418,x=5.8,y=47.4,n="Galamav the Marksman"},f={i=1,n="Commander Gor'shak"},st="Galamav the Marksman, Badlands",ft="Commander Gor'shak",oe="Find Commander Gor'shak in Blackrock Depths. You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.",of="Trouver le commandant Gor'shak dans les Profondeurs de Blackrock.\n\nLe dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison.",xp=9450,sh=true}
ns.Q[3982]={n="What Is Going On?",nf="Que se passe-t-il ?",l=54,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={3981},s={i=1,n="Commander Gor'shak"},f={i=1,n="Commander Gor'shak"},st="Commander Gor'shak, Blackrock Depths",ft="Commander Gor'shak, Blackrock Depths",o={{k="kill",n="Commander Gor'shak",ins=false,unk=true,ns=false,t={"Commander Gor'shak"}}},oe="Defend Gor'shak.",of="Défendre Gor'shak.",ne="Open his cell with the Prison Cell Key from High Interrogator Gerstahn, then defend him.",xp=10100,sh=false}
ns.Q[4001]={n="What Is Going On?",nf="Que se passe-t-il ?",l=54,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={3982},s={i=1,n="Commander Gor'shak"},f={m=1454,x=31.7,y=37.8,n="Thrall"},st="Commander Gor'shak",ft="Thrall, Orgrimmar",o={{k="kill",n="Kharan Mighthammer",ins=false,unk=true,ns=false,t={"Kharan Mighthammer"}}},oe="Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby.",of="Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar.\n\nGor'shak a dit que Kharan était détenu dans une cellule proche.",xp=12600,sh=true}
ns.Q[4002]={n="The Eastern Kingdoms",nf="Les Royaumes de l'est",l=54,r=48,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="pre",p={4001},s={m=1454,x=32,y=37.8,n="Thrall"},f={m=1454,x=31.7,y=37.8,n="Thrall"},st="Thrall, Orgrimmar",ft="Thrall, Orgrimmar",oe="Speak with Thrall if you are prepared to take on the mission he has planned.",of="Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue.",xp=550,sh=true}
ns.Q[7604]={n="A Binding Contract",nf="Un contrat contraignant",l=60,r=60,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",s={i=1,n="Thorium Brotherhood Contract"},f={i=1,n="Lokhtos Darkbargainer"},st="Thorium Brotherhood Contract (from Lokhtos Darkbargainer with a Sulfuron Ingot)",ft="Lokhtos Darkbargainer, Grim Guzzler, Blackrock Depths",o={{k="item",n="Thorium Brotherhood Contract",c=1,ins=false,unk=false,ns=true},{k="item",n="Sulfuron Ingot",c=1,ins=false,unk=true,ns=false,t={"Golemagg the Incinerator"},src={{"Golemagg the Incinerator",37}}}},oe="Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",of="Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron.",ne="Blacksmithing. Bring a Sulfuron Ingot (Golemagg, Molten Core) to Lokhtos in the Grim Guzzler to get the contract, then hand it back for the Sulfuron Hammer plans.",ri={"Plans: Sulfuron Hammer"},xp=6600,sh=false,si="Thorium Brotherhood Contract",sid=18628,prof="BLACKSMITHING"}
ns.Q[97197]={n="Fragment of the Firelands",l=55,r=46,fa="Horde",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",s={m=1412,x=33.4,y=22.5,n="Alaana Stormwalker"},f={m=1412,x=33.4,y=22.5,n="Alaana Stormwalker"},st="Alaana Stormwalker, Skywatcher Plateau, Mulgore (33.4, 22.5)",ft="Alaana Stormwalker, Skywatcher Plateau, Mulgore (33.4, 22.5)",oe="Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore.",ne="Get the fragment from the Firelands elementals inside Blackrock Depths. Which one drops it isn't confirmed yet; please report it on Discord. Seen picked up at level 49.",rw="85s  •  Cenarion Circle +300",xp=14800}
ns.Q[9015]={n="The Challenge",nf="Le défi",l=60,r=58,fa="Both",d="BlackrockDepths",ds={"BlackrockDepths"},role="main",p={8913,8914,8915,8916,8917,8918,8919,8920,8923,8921,8924,8925,8928,8978,8927,8938,8939,8940,8941,8942,8943,8944,8930,8945,8946,8947,8948,8949,8950,8905,8906,8907,8909,8910,8908,8911,8912,8922,8977,8926,8931,8932,8934,8935,8933,8936,8937,8929},s={i=1,n="Falrin Treeshaper"},f={m=1423,x=26.1,y=11.3,n="Anthion Harmon"},st="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",ft="Anthion Harmon, outside Stratholme, Eastern Plaguelands",o={{k="kill",n="Theldren Kill Credit",c=1,ins=false,unk=true,ns=false,t={"Theldren Kill Credit"}},{k="item",n="Top Piece of Lord Valthalak's Amulet",c=1,ins=false,unk=true,ns=false,t={"Theldren"},src={{"Theldren",100}}}},oe="Use the Banner of Provocation in the center of the Ring of Law as High Justice Grimstone sentences you, slay Theldren and his gladiators, and bring the Top Piece of Lord Valthalak's Amulet to Anthion Harmon in the Eastern Plaguelands.",of="Rendez-vous dans le Cercle de la loi, dans les profondeurs de Blackrock, et placez la Bannière de provocation en son centre lorsque vous serez <condamné/condamnée> par le Juge supérieur Grimstone. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’est avec le premier morceau de l’amulette du seigneur Valthalak.",ne="Plant the banner before the normal challenger comes out. Theldren and his gladiators then fight you, and an Arena Spoils chest appears afterwards. You keep the banner (10 min cooldown) to summon him again.",rw="1,450 XP",xp=13200,req={{"Top Piece of Lord Valthalak's Amulet",1,"Dropped by Theldren in the Ring of Law, Blackrock Depths"}}}
ns.Q[8948]={n="Anthion's Old Friend",nf="Le vieil ami d'Anthion",l=60,r=58,fa="Both",d="BlackrockDepths",od="DireMaulEast",ds={"BlackrockDepths"},role="pre",p={8947},s={m=1423,x=26.1,y=11.3,n="Anthion Harmon"},f={i=1,n="Falrin Treeshaper"},st="Anthion Harmon, outside Stratholme, Eastern Plaguelands",ft="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",o={{k="item",n="Incomplete Banner of Provocation",c=1,ins=false,unk=false,ns=true}},oe="Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.",of="Apportez la Bannière de défi incomplète à Farlin Treeshaper, dans la bibliothèque de Hache-tripes.",xp=13200}
ns.Q[8949]={n="Falrin's Vendetta",nf="La vendetta de Falrin",l=60,r=58,fa="Both",d="BlackrockDepths",od="DireMaulEast",ds={"BlackrockDepths"},role="pre",p={8948},s={i=1,n="Falrin Treeshaper"},f={i=1,n="Falrin Treeshaper"},st="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",ft="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",o={{k="item",n="Ogre Warbeads",c=25,ins=false,unk=true,ns=false,t={"Stomper Kreeg","Guard Slip'kik","Cho'Rush the Observer"},src={{"Stomper Kreeg",50},{"Guard Slip'kik",50},{"Cho'Rush the Observer",50}}}},oe="Collect 25 Ogre Warbeads from ogres inside Dire Maul or Blackrock Spire.",of="Collecter 25 Perles de guerre ogres à l’intérieur de Hache-tripes ou du Pic Blackrock, puis revenir voir Falrin Treeshaper, à l'intérieur de l'Athenaeum à Hache-tripes.",ri={"Beads of Ogre Mojo","Beads of Ogre Might"},rc=true,xp=13200,req={{"Ogre Warbeads",1,"From ogres in Dire Maul or Blackrock Spire (25 needed)"}}}
ns.Q[8950]={n="The Instigator's Enchantment",nf="L'enchantement du provocateur",l=60,r=58,fa="Both",d="BlackrockDepths",od="Scholomance",ds={"BlackrockDepths"},role="pre",p={8949},s={i=1,n="Falrin Treeshaper"},f={i=1,n="Falrin Treeshaper"},st="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",ft="Falrin Treeshaper, the Athenaeum, Dire Maul (West)",o={{k="item",n="Jeering Spectre's Essence",c=1,ins=false,unk=true,ns=false,t={"Eldreth Sorcerer","Eldreth Apparition","Eldreth Spirit"},src={{"Eldreth Sorcerer",20},{"Eldreth Apparition",20},{"Eldreth Spirit",20}}},{k="item",n="Dark Rune",c=4,ins=false,unk=true,ns=false,t={"Lady Illucia Barov","Instructor Malicia","The Ravenian"},src={{"Lady Illucia Barov",51.4},{"Instructor Malicia",44},{"The Ravenian",44}}},{k="item",n="Large Brilliant Shard",c=8,ins=false,unk=false,ns=true}},oe="Bring 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards to Falrin Treeshaper inside Dire Maul.",of="Apportez les choses suivantes à Falrin Treeshaper dans Hache-tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants.",xp=13200,req={{"Jeering Spectre's Essence",1,"From Eldreth Phantasms, Spectres, Spirits and Apparitions in Dire Maul (1 needed)"},{"Dark Rune",2,"From undead in the Plaguelands, Scholomance and Stratholme (4 needed)"},{"Large Brilliant Shard",3,"Enchanting: disenchant rare items, or buy one (8 needed)"}}}
ns.Q[4742]={n="Seal of Ascension",nf="Le sceau de l'ascension",l=60,r=57,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire","UpperBlackrockSpire"},role="main",s={i=1,n="Scarshield Infiltrator"},f={i=1,n="Scarshield Infiltrator"},st="Scarshield Infiltrator (Scarshield Infiltrator), Lower Blackrock Spire",ft="Scarshield Infiltrator (Scarshield Infiltrator), Lower Blackrock Spire",o={{k="item",n="Gemstone of Spirestone",c=1,ins=false,unk=true,ns=false,t={"Highlord Omokk"},src={{"Highlord Omokk",13}}},{k="item",n="Gemstone of Smolderthorn",c=1,ins=false,unk=true,ns=false,t={"War Master Voone"},src={{"War Master Voone",17}}},{k="item",n="Gemstone of Bloodaxe",c=1,ins=false,unk=true,ns=false,t={"Overlord Wyrmthalak"},src={{"Overlord Wyrmthalak",26}}},{k="item",n="Unadorned Seal of Ascension",c=1,ins=false,unk=false,ns=false,outer=true,w={m=1428,x=32.6,y=31.8,n="Scarshield Sentry"},t={"Urok Doomhowl","Scarshield Grunt","Scarshield Sentry"},src={{"Urok Doomhowl",5},{"Scarshield Grunt",5},{"Scarshield Sentry",5}}}},oe="Find the three gemstones of command: the Gemstone of Smolderthorn, Gemstone of Spirestone and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Scarshield Infiltrator. The generals are War Master Voone of the Smolderthorn, Highlord Omokk of the Spirestone and Overlord Wyrmthalak of the Bloodaxe.",of="Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Scarshield Infiltrator.\n\nLes généraux, comme vous l'a dit Scarshield Infiltrator, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe.",xp=16200,sh=true,req={{"Gemstone of Spirestone",2,"Dropped by Highlord Omokk, Lower Blackrock Spire"},{"Gemstone of Smolderthorn",2,"Dropped by War Master Voone, Lower Blackrock Spire"},{"Gemstone of Bloodaxe",2,"Dropped by Overlord Wyrmthalak, Lower Blackrock Spire"},{"Unadorned Seal of Ascension",1,"Random drop from Blackrock Spire trash"}}}
ns.Q[4981]={n="Operative Bijou",nf="Agent Bijou",l=59,r=55,fa="Horde",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",s={m=1418,x=5.8,y=47.4,n="Lexlort"},f={i=1,n="Bijou"},st="Lexlort, Kargath, Badlands",ft="Bijou, inside Lower Blackrock Spire",oe="Travel to Blackrock Spire and find out what happened to Bijou.",of="Aller au pic Rochenoire et découvrir ce qui est arrivé à Bijou.",xp=11850,sh=true}
ns.Q[4982]={n="Bijou's Belongings",nf="Les effets de Bijou",l=59,r=55,fa="Horde",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",p={4981},s={i=1,n="Bijou"},f={i=1,n="Bijou"},st="Bijou, Lower Blackrock Spire",ft="Bijou, Lower Blackrock Spire",o={{k="item",n="Bijou's Belongings",c=1,ins=false,unk=true,ns=false,src={{"Bijou's Belongings",100}}}},oe="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.",of="Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville.",ne="Then take Bijou's Reconnaissance Report to Lexlort in Kargath for the reward.",rw="1g 80s",ri={"Freewind Gloves","Seapost Girdle"},rc=true,xp=11850,sh=true}
ns.Q[4903]={n="Warlord's Command",nf="Ordre du chef de guerre",l=60,r=55,fa="Horde",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire","UpperBlackrockSpire"},role="main",p={98325},s={m=1418,x=5.8,y=47.4,n="Warlord Goretooth"},f={m=1418,x=5.8,y=47.5,n="Warlord Goretooth"},st="Warlord Goretooth, Kargath, Badlands",ft="Warlord Goretooth, Kargath, Badlands",o={{k="kill",n="Overlord Wyrmthalak",c=1,ins=false,unk=true,ns=false,t={"Overlord Wyrmthalak"}},{k="kill",n="Highlord Omokk",c=1,ins=false,unk=true,ns=false,t={"Highlord Omokk"}},{k="kill",n="War Master Voone",c=1,ins=false,unk=true,ns=false,t={"War Master Voone"}},{k="item",n="Important Blackrock Documents",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1433,x=64.7,y=56.1,n="Singe"},t={"Singe","Spirestone Battle Mage","Spirestone Mystic"},src={{"Singe",100},{"Spirestone Battle Mage",100},{"Spirestone Mystic",100}}}},oe="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",of="Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents de Rochenoire. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie.",ne="Talk to Goretooth to receive his Command item and click it to start the quest. The Important Blackrock Documents spawn near the three generals.",ri={"Wyrmthalak's Shackles","Omokk's Girth Restrainer","Halycon's Muzzle","Vosh'gajin's Strand","Voone's Vice Grips"},rc=true,xp=15350,sh=false,si="Warlord Goretooth's Command",sid=12563}
