ns.Q[4729]={n="Kibler's Exotic Pets",nf="Les animaux exotiques de Kibler",l=59,r=55,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",s={m=1428,x=65.8,y=22,n="Kibler"},f={m=1428,x=65.9,y=21.9,n="Kibler"},st="Kibler, Flame Crest, Burning Steppes",ft="Kibler, Flame Crest, Burning Steppes",o={{k="item",n="Caged Worg Pup",c=1,ins=false,unk=false,ns=true}},oe="Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.",of="Aller au pic Rochenoire et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler.",ne="Use the supplied cage on a Bloodaxe Worg Pup in the worg area.",ri={"Worg Carrier"},xp=12500,sh=false}
ns.Q[4862]={n="En-Ay-Es-Tee-Why",nf="Mauvais",l=59,r=55,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",s={m=1428,x=65.8,y=22,n="Kibler"},f={m=1428,x=65.9,y=21.9,n="Kibler"},st="Kibler, Flame Crest, Burning Steppes",ft="Kibler, Flame Crest, Burning Steppes",o={{k="item",n="Spire Spider Egg",c=15,ins=false,unk=true,ns=false,src={{"Spire Spider Egg",100},{"Spire Spider Egg",100}}}},oe="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler. By the sound of it, these eggs could be found near spiders.",of="Aller au pic Rochenoire et ramasser 15 Oeuf d'araignée du pic pour Kibler.\n\nCes oeufs peuvent être trouvés à proximité des araignées.",ne="Spire Spider Eggs are in the spider tunnels.",ri={"Smolderweb Carrier"},xp=12500,sh=true}
ns.Q[4866]={n="Mother's Milk",nf="Le lait matriarcal",l=60,r=55,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",s={m=1428,x=65,y=23.6,n="Ragged John"},f={m=1428,x=65,y=23.8,n="Ragged John"},st="Ragged John, Flame Crest, Burning Steppes",ft="Ragged John, Flame Crest, Burning Steppes",o={{k="kill",n="Ragged John",ins=false,unk=false,ns=false,outer=false,w={m=1428,x=65,y=23.8,n="Ragged John"},t={"Ragged John"}}},oe="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Return to Ragged John while poisoned so that he can 'milk' you.",of="Vous trouverez la Matriarche Couveuse au coeur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon.",ne="Get poisoned by Mother Smolderweb and reach Ragged John while still poisoned. Don't let anyone cleanse it.",ri={"Ragged John's Neverending Cup"},xp=18900,sh=true}
ns.Q[4867]={n="Urok Doomhowl",nf="Urok Hurleruine",l=60,r=55,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",s={i=1,n="Warosh"},f={i=1,n="Warosh"},st="Warosh, Lower Blackrock Spire",ft="Warosh, Lower Blackrock Spire",o={{k="item",n="Warosh's Mojo",c=1,ins=false,unk=true,ns=false,t={"Urok Doomhowl"},src={{"Urok Doomhowl",100}}}},oe="Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.",of="Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh.",ne="Bring Highlord Omokk's Head and a Roughshod Pike to Urok's Tribute Pile beyond the spiders to start the waves. Warosh walks around the first halls after the entrance: if he is not where you expect him, wait a moment or look along those halls.",ri={"Prismcharm"},xp=18900,sh=false}
ns.Q[4788]={n="The Final Tablets",nf="Les dernières tablettes",l=58,r=40,fa="Both",d="LowerBlackrockSpire",ds={"LowerBlackrockSpire"},role="main",p={3520,3527,4787,3528,5065},s={m=1446,x=66.8,y=24,n="Prospector Ironboot"},f={m=1446,x=66.9,y=24,n="Prospector Ironboot"},st="Prospector Ironboot, Steamwheedle Port, Tanaris",ft="Prospector Ironboot, Steamwheedle Port, Tanaris",o={{k="item",n="Fifth Mosh'aru Tablet",c=1,ins=false,unk=true,ns=false,src={{"Fifth Mosh'aru Tablet",100}}},{k="item",n="Sixth Mosh'aru Tablet",c=1,ins=false,unk=true,ns=false,src={{"Sixth Mosh'aru Tablet",100}}}},oe="Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",of="Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris.",ne="The fifth and sixth Mosh'aru tablets are in the Smolderthorn troll area. Continues with Confront Yeh'kinya and The Hand of Rastakhan.",xp=15100,sh=true}
