ns.Q[6582]={n="The Test of Skulls, Scryer",nf="L'épreuve des crânes, Clairvoyant",l=60,r=55,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",p={6570},s={m=1445,x=56.2,y=88,n="Emberstrife"},f={m=1445,x=56.6,y=87.8,n="Emberstrife"},st="Emberstrife, Dustwallow Marsh",ft="Emberstrife, Dustwallow Marsh",o={{k="item",n="The Skull of Scryer",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1452,x=52.7,y=55.9,n="Scryer"},t={"Scryer"},src={{"Scryer",100}}}},oe="You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife. You know that Scryer can be found in Winterspring.",of="Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.\n\nClairvoyant se trouve au Berceau-de-l'Hiver.",xp=6600,sh=true}
ns.Q[6583]={n="The Test of Skulls, Somnus",nf="L'épreuve des crânes, Somnus",l=60,r=55,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",p={6570},s={m=1445,x=56.2,y=88,n="Emberstrife"},f={m=1445,x=56.6,y=87.8,n="Emberstrife"},st="Emberstrife, Dustwallow Marsh",ft="Emberstrife, Dustwallow Marsh",o={{k="item",n="The Skull of Somnus",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1435,x=76,y=66.6,n="Somnus"},t={"Somnus"},src={{"Somnus",100}}}},oe="Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.",of="Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre.",xp=6600,sh=true}
ns.Q[6584]={n="The Test of Skulls, Chronalis",nf="L'épreuve des crânes, Chronalis",l=60,r=55,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",p={6570},s={m=1445,x=56.2,y=88,n="Emberstrife"},f={m=1445,x=56.6,y=87.8,n="Emberstrife"},st="Emberstrife, Dustwallow Marsh",ft="Emberstrife, Dustwallow Marsh",o={{k="item",n="The Skull of Chronalis",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1446,x=64.2,y=48.5,n="Chronalis"},t={"Chronalis"},src={{"Chronalis",100}}}},oe="Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.",of="Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre.",xp=6600,sh=true}
ns.Q[6585]={n="The Test of Skulls, Axtroz",nf="L'épreuve des crânes, Axtroz",l=60,r=55,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",p={6582,6583,6584},s={m=1445,x=56.2,y=88,n="Emberstrife"},f={m=1445,x=56.6,y=87.8,n="Emberstrife"},st="Emberstrife, Dustwallow Marsh",ft="Emberstrife, Dustwallow Marsh",o={{k="item",n="The Skull of Axtroz",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1437,x=81.8,y=48.2,n="Axtroz"},t={"Axtroz"},src={{"Axtroz",100}}}},oe="Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",of="Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre.",xp=6600,sh=true}
ns.Q[6601]={n="Ascension...",l=60,r=55,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",p={6585},s={m=1445,x=56.2,y=88,n="Emberstrife"},f={m=1442,x=29.5,y=77.5,n="Rexxar"},st="Emberstrife, Dustwallow Marsh",ft="Rexxar, Feralas",o={{k="item",n="Dull Drakefire Amulet",c=1,ins=false,unk=false,ns=true}},oe="It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.",of="Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire.",xp=4950,sh=false}
ns.Q[5127]={n="The Demon Forge",nf="La forge démoniaque",l=60,r=55,c="WARRIOR,PALADIN,SHAMAN",fa="Both",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="main",p={5126},s={m=1452,x=63.8,y=73.8,n="Lorax"},f={m=1452,x=63.8,y=73.8,n="Lorax"},st="Lorax, Winterspring",ft="Lorax, Winterspring",o={{k="item",n="Soul Stained Pike",c=1,ins=false,unk=false,ns=true},{k="item",n="Unforged Rune Covered Breastplate",c=1,ins=false,unk=true,ns=false,src={{"Unforged Runic Breastplate",100}}}},oe="Travel to Blackrock Spire, slay Goraluk Anvilcrack and use the Blood Stained Pike on his corpse. Also find the Unforged Rune Covered Breastplate. Return the Soul Stained Pike and the breastplate to Lorax in Winterspring.",of="Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.\n\nTrouver aussi la Cuirasse couverte de runes inachevée.\n\nRapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver.",ne="Blacksmithing 270 (Armorsmith). Use the Blood Stained Pike on Goraluk's corpse and loot the Unforged Rune Covered Breastplate nearby.",ri={"Plans: Demon Forged Breastplate","Demon Kissed Sack","Elixir of Demonslaying"},xp=16600,sh=false,prof="BLACKSMITHING"}
ns.Q[5126]={n="Lorax's Tale",l=60,r=55,c="WARRIOR,PALADIN,SHAMAN",fa="Both",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="pre",s={m=1452,x=63.8,y=73.8,n="Lorax"},f={m=1452,x=63.8,y=73.8,n="Lorax"},o={{k="kill",n="Lorax",ins=false,unk=false,ns=false,outer=false,w={m=1452,x=63.8,y=73.8,n="Lorax"},t={"Lorax"}}},xp=660}
ns.Q[4768]={n="The Darkstone Tablet",nf="La tablette de Darkstone",l=60,r=57,fa="Horde",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="main",s={m=1418,x=3,y=47.6,n="Shadowmage Vivian Lagrave"},f={m=1418,x=2.9,y=47.8,n="Shadowmage Vivian Lagrave"},st="Shadowmage Vivian Lagrave, Kargath, Badlands",ft="Shadowmage Vivian Lagrave, Kargath, Badlands",o={{k="item",n="Darkstone Tablet",c=1,ins=false,unk=true,ns=false,src={{"Darkstone Tablet",100}}}},oe="Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.",of="Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath.",ne="The Darkstone Tablet lies on the ground in the Rookery.",rw="2g 70s",ri={"Swiftfoot Treads","Blinkstrike Armguards"},rc=true,xp=22200,sh=true}
ns.Q[5047]={n="Pip Quickwit, At Your Service!",nf="Pip Quickwit, à votre service !",l=60,r=57,fa="Both",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="main",s={i=1,n="From The Beast's corpse"},f={m=1452,x=61,y=38.8,n="Malyfous Darkhammer"},st="From The Beast's corpse, Upper Blackrock Spire",ft="Malyfous Darkhammer, Everlook, Winterspring",o={{k="item",n="Glowing Hunk of the Beast's Flesh",c=1,ins=false,unk=false,ns=true}},oe="Talk to Malyfous Darkhammer in Everlook.",of="Parler à Malyfous Darkhammer à Long-guet.",ne="He appears from The Beast's corpse after the fight. Malyfous then offers the Pristine Hide of the Beast exchanges.",xp=17650,sh=false}
ns.Q[5160]={n="The Matron Protectorate",nf="Le Protectorat de la matrone",l=60,r=57,fa="Both",d="UpperBlackrockSpire",ds={"UpperBlackrockSpire"},role="main",s={i=1,n="Awbee"},f={m=1452,x=54.5,y=51.2,n="Haleh"},st="Awbee, Upper Blackrock Spire",ft="Haleh, Mazthoril, Winterspring",o={{k="item",n="Awbee's Scale",c=1,ins=false,unk=false,ns=true}},oe="Travel to Winterspring and find Haleh. Give her Awbee's scale.",of="Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee.",ne="Awbee is the wounded blue dragon near the arena route after Rend. Use the rune deep in the Mazthoril cave to reach Haleh.",xp=17650,sh=false}
ns.Q[7441]={n="Pusillin and the Elder Azj'Tordin",nf="Pusillin et l'Ancien Azj'Tordin",l=58,r=54,fa="Both",d="DireMaulEast",ds={"DireMaulEast"},role="main",s={m=1444,x=76.8,y=37.4,n="Azj'Tordin"},f={m=1444,x=76.9,y=37.3,n="Azj'Tordin"},st="Azj'Tordin, Lariss Pavilion, Feralas",ft="Azj'Tordin, Lariss Pavilion, Feralas",o={{k="item",n="Book of Incantations",c=1,ins=false,unk=true,ns=false,t={"Pusillin"},src={{"Pusillin",100}}}},oe="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",of="Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.\n\nSi vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas.",ne="Chase and talk to Pusillin through the wing until he fights, then kill him for the book. He also drops the Crescent Key.",rw="1g 75s",ri={"Spry Boots","Sprinter's Sword"},rc=true,xp=20750,sh=true}
ns.Q[7489]={n="Lethtendris's Web",nf="Le filet de Lethtendris",l=57,r=54,fa="Horde",d="DireMaulEast",ds={"DireMaulEast"},role="main",s={m=1444,x=76,y=43.8,n="Talo Thornhoof"},f={m=1444,x=76.2,y=43.8,n="Talo Thornhoof"},st="Talo Thornhoof, Camp Mojache, Feralas",ft="Talo Thornhoof, Camp Mojache, Feralas",o={{k="item",n="Lethtendris's Web",c=1,ins=false,unk=true,ns=false,t={"Lethtendris"},src={{"Lethtendris",100}}}},oe="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",of="Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas.",ne="The web drops from Lethtendris.",rw="1g 70s",ri={"Lorespinner"},xp=20200,sh=true}
ns.Q[5526]={n="Shards of the Felvine",nf="Fragment de la Gangrevigne",l=60,r=56,fa="Both",d="DireMaulEast",ds={"DireMaulEast"},role="main",p={5527},s={m=1450,x=51.6,y=44.4,n="Rabine Saturna"},f={m=1450,x=51.7,y=45.1,n="Rabine Saturna"},st="Rabine Saturna, Nighthaven, Moonglade",ft="Rabine Saturna, Nighthaven, Moonglade",o={{k="item",n="Sealed Reliquary of Purity",c=1,ins=false,unk=false,ns=true}},oe="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.",of="Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit.",ne="Kill Alzzin the Wildshaper, pick up a Felvine Shard near the vine and seal it in the Reliquary of Purity.",ri={"Milli's Shield","Milli's Lexicon"},rc=true,xp=22200,sh=false}
ns.Q[5527]={n="A Reliquary of Purity",nf="Un reliquaire de pureté",l=60,r=56,fa="Both",d="DireMaulEast",ds={"DireMaulEast"},role="pre",s={m=1450,x=51.6,y=44.4,n="Rabine Saturna"},f={m=1450,x=51.7,y=45.1,n="Rabine Saturna"},st="Rabine Saturna, Moonglade",ft="Rabine Saturna, Moonglade",o={{k="item",n="Reliquary of Purity",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1451,x=63.2,y=55.3,n="Dusty Reliquary"},src={{"Dusty Reliquary",100}}}},oe="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.",of="Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune.",xp=6600,sh=true}
ns.Q[7463]={n="Arcane Refreshment",nf="Rafraîchissement arcanique",l=60,r=60,c="MAGE",fa="Both",d="DireMaulEast",ds={"DireMaulEast"},role="main",s={i=1,n="Lorekeeper Lydros"},f={i=1,n="Lorekeeper Lydros"},st="Lorekeeper Lydros, Dire Maul",ft="Lorekeeper Lydros, Dire Maul",o={{k="item",n="Hydrospawn Essence",c=1,ins=false,unk=true,ns=false,t={"Hydrospawn"},src={{"Hydrospawn",100}}}},oe="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.",of="Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos.",ne="Mage class quest. Lydros is in the Athenaeum (North/West); Hydrospawn Essence drops from Hydrospawn in East. Rewards Conjure Water (Rank 7).",xp=13200,sh=true}
ns.Q[7461]={n="The Madness Within",nf="Folie intérieure",l=60,r=56,fa="Both",d="DireMaulWest",ds={"DireMaulWest"},role="main",s={i=1,n="Shen'dralar Ancient"},f={i=1,n="Shen'dralar Ancient"},st="Shen'dralar Ancient, Dire Maul",ft="Shen'dralar Ancient, Dire Maul",o={{k="kill",n="Immol'thar",c=1,ins=false,unk=true,ns=false,t={"Immol'thar"}},{k="kill",n="Prince Tortheldrin",c=1,ins=false,unk=true,ns=false,t={"Prince Tortheldrin"}}},oe="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest.",of="Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.\n\nEntrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.\n\nLorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour.",ne="Kill the guardians of all five pylons, then Immol'thar, then Prince Tortheldrin. Return to the Ancient, take The Treasure of the Shen'dralar and open the chest under the library stairs for the reward.",rw="2g 70s",ri={"Bonecrusher","Backwood Helm","Sedge Boots"},rc=true,xp=23650,sh=true}
ns.Q[7482]={n="Elven Legends",l=60,r=54,fa="Alliance",d="DireMaulNorth",ds={"DireMaulWest","DireMaulNorth"},role="main",s={m=1444,x=31.2,y=43.4,n="Scholar Runethorn"},f={m=1444,x=31.2,y=43.4,n="Scholar Runethorn"},st="Scholar Runethorn, Feathermoon Stronghold, Feralas",ft="Scholar Runethorn, Feathermoon Stronghold, Feralas",o={{k="object",n="Skeletal Remains of Telmius Dreamseeker",ins=false,unk=true,ns=false}},oe="Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.",ne="Interact with the Skeletal Remains of Telmius Dreamseeker beside Lorekeeper Lydros in the Athenaeum. Unlocks Lydros's libram exchanges.",xp=19713,sh=true}
ns.Q[7481]={n="Elven Legends",nf="Légendes elfiques",l=60,r=54,fa="Horde",d="DireMaulNorth",ds={"DireMaulWest","DireMaulNorth"},role="main",s={m=1444,x=74.4,y=44,n="Sage Korolusk"},f={m=1444,x=74.4,y=44,n="Sage Korolusk"},st="Sage Korolusk, Camp Mojache, Feralas",ft="Sage Korolusk, Camp Mojache, Feralas",o={{k="object",n="Skeletal Remains of Telmius Dreamseeker",ins=false,unk=true,ns=false}},oe="Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.",of="Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache.",ne="Interact with the Skeletal Remains of Telmius Dreamseeker beside Lorekeeper Lydros in the Athenaeum. Unlocks Lydros's libram exchanges.",rw="1g 80s",xp=19713,sh=true,conf={"naowh","zygor"}}
ns.Q[7703]={n="Unfinished Gordok Business",nf="Affaires inachevées chez les Gordok",l=60,r=56,fa="Both",d="DireMaulNorth",ds={"DireMaulWest","DireMaulNorth"},role="main",s={i=1,n="Captain Kromcrush"},f={i=1,n="Captain Kromcrush"},st="Captain Kromcrush, Dire Maul",ft="Captain Kromcrush, Dire Maul",o={{k="item",n="Gauntlet of Gordok Might",c=1,ins=false,unk=true,ns=false,src={{"The Prince's Chest",100}}}},oe="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",of="Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes.\n\nSelon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok.",ne="West objective: the Gauntlet of Gordok Might is in a chest near Prince Tortheldrin. The quest itself comes from a friendly Captain Kromcrush in Dire Maul North after you become the Gordok king.",ri={"Gordok's Handguards","Gordok's Gauntlets","Gordok's Gloves","Gordok's Handwraps"},rc=true,xp=22200,sh=false}
ns.Q[7631]={n="Dreadsteed of Xoroth",nf="Le destrier de l'effroi de Xoroth",l=60,r=60,c="WARLOCK",fa="Both",d="DireMaulWest",ds={"DireMaulWest"},role="main",p={7563,7564,7623,7624,7625,7626,7627,7628,7630,7629},s={m=1428,x=12.6,y=31.4,n="Mor'zul Bloodbringer"},f={i=1,n="Dreadsteed Spirit"},st="Mor'zul Bloodbringer, Altar of Storms, Burning Steppes",ft="Dreadsteed Spirit, Dire Maul",o={{k="kill",n="Xorothian Dreadsteed",c=1,ins=false,unk=true,ns=false,t={"Xorothian Dreadsteed"}}},oe="Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.",of="Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit.",ne="Warlock dreadsteed quest. After Immol'thar dies, run the ritual in his prison with J'eevee's Jar, the Black Lodestone and the Xorothian Glyphs. Bring Soul Shards.",xp=13200,sh=false}
ns.Q[7563]={n="Rage of Blood",nf="Rage de sang",l=58,r=60,c="WARLOCK",fa="Both",d="DireMaulWest",ds={"DireMaulWest"},role="pre",s={m=1428,x=12.6,y=31.4,n="Mor'zul Bloodbringer"},f={m=1428,x=12.7,y=31.6,n="Mor'zul Bloodbringer"},st="Mor'zul Bloodbringer, Burning Steppes",ft="Mor'zul Bloodbringer, Burning Steppes",o={{k="item",n="Raging Beast's Blood",c=30,ins=false,unk=false,ns=false,outer=false,w={m=1452,x=28.5,y=48.3,n="Ragged Owlbeast"},t={"Ragged Owlbeast","Raging Owlbeast","Crazed Owlbeast"},src={{"Ragged Owlbeast",35},{"Raging Owlbeast",35},{"Crazed Owlbeast",35}}}},oe="Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.",of="Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes.",xp=8300,sh=true}
ns.Q[7564]={n="Wildeyes",nf="Gorzeeki Wildeyes",l=58,r=60,c="WARLOCK",fa="Both",d="DireMaulWest",ds={"DireMaulWest"},role="pre",p={7563},s={m=1428,x=12.6,y=31.4,n="Mor'zul Bloodbringer"},f={m=1428,x=12.4,y=31.6,n="Gorzeeki Wildeyes"},st="Mor'zul Bloodbringer, Burning Steppes",ft="Gorzeeki Wildeyes, Burning Steppes",o={{k="item",n="Case of Blood",c=1,ins=false,unk=false,ns=true}},oe="Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.",of="Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes.",xp=3300,sh=false}
