ns.Q[86777]={n="Master Feardred",l=53,r=47,fa="Horde",d="BlackmawHold",ds={"BlackmawHold"},role="pre",s={m=1447,x=63,y=23.3,n="Korsa"},f={m=1447,x=63,y=23.3,n="Korsa"},st="Korsa, outside Legashi Stronghold, Azshara (63.0, 23.3)",ft="Korsa, outside Legashi Stronghold, Azshara (63.0, 23.3)",o={{k="item",n="Feardred's Amulet",c=1,ins=false,unk=false,t={"Master Feardred"}}},oe="Kill Master Feardred, and bring his amulet to Korsa.",ne="Master Feardred, a servant of Varrox Bleakhoof, has a camp south of Korsa that you can see from where she stands. Kill him, loot Feardred's Amulet and bring it to Korsa.",xp=5250,req={{"Feardred's Amulet",1,"From Master Feardred"}}}
