ns.Q[86796]={n="Later, Satyr",l=54,r=47,fa="Horde",d="BlackmawHold",ds={"BlackmawHold"},role="pre",s={m=1447,x=65.9,y=14.4,n="Graal"},f={m=1447,x=63,y=23.3,n="Korsa"},st="Graal, caged in Legashi Stronghold, Azshara (65.9, 14.4)",ft="Korsa, outside Legashi Stronghold, Azshara (63.0, 23.3)",o={{k="event",n="Graal",c=1,ins=false,unk=false,w={m=1447,x=65.9,y=14.4,n="Graal"}}},oe="Help Graal break out of Legashi Stronghold, then inform Korsa outside Legashi Stronghold.",ne="Graal is a satyr scout caged in Legashi Stronghold (65.9, 14.4). Accept the quest and help him get out: he is outnumbered, so protect him from the Legashi guards on the way. Then tell Korsa outside the stronghold.",xp=5450}
