ns.Q[87346]={n="Chieftain Bloodmaw",l=55,r=47,fa="Both",d="BlackmawHold",ds={"BlackmawHold"},role="pre",s={m=1448,x=65.2,y=2.6,n="Gorn One Eye"},f={m=1448,x=65.2,y=2.6,n="Gorn One Eye"},st="Gorn One Eye, Timbermaw Hold",ft="Gorn One Eye, Timbermaw Hold",o={{k="item",n="Bloodmaw's Basher",c=1,ins=false,unk=false,t={"Chieftain Bloodmaw"},w={m=1448,x=62,y=10,n="Felpaw Village"}}},oe="Kill Chieftain Bloodmaw and bring his mace to Gorn One Eye in Timbermaw Hold.",ne="Chieftain Bloodmaw leads the Deadwood furbolgs in Felpaw Village, north Felwood, just south of the Timbermaw Hold tunnel (the map point is approximate). Fight through the village, kill him, loot Bloodmaw's Basher and bring it to Gorn One Eye.",xp=5650,req={{"Bloodmaw's Basher",1,"From Chieftain Bloodmaw"}}}
ns.Q[86814]={n="Blackmaw Counter-Offensive",l=55,r=47,fa="Both",d="BlackmawHold",ds={"BlackmawHold"},role="pre",s={m=1448,x=65.2,y=2.6,n="Gorn One Eye"},f={m=1447,x=42.4,y=20.2,n="Gatekeeper Rageroar"},st="Gorn One Eye, Timbermaw Hold",ft="Gatekeeper Rageroar, Ursolan, Azshara (42.4, 20.2)",o={{k="object",n="Timbermaw War Banner",c=1,ins=false,unk=false,w={m=1447,x=65,y=17,n="Legashi Stronghold"}},{k="kill",n="Prince Halanox",c=1,ins=false,unk=false,w={m=1447,x=65,y=17,n="Legashi Stronghold"}}},oe="Plant the Timbermaw War Banner at the Legashi Stronghold in Azshara. Kill Prince Halanox, report your victory to Gatekeeper Rageroar at Ursolan.",ne="Gorn One Eye gives you the Timbermaw War Banner. In Legashi Stronghold, Azshara, find Prince Halanox's demonic summoning circle and use the banner there: Halanox comes out and Timbermaw allies join the fight. Kill him, then report to Gatekeeper Rageroar at Ursolan. The map point is the middle of the stronghold, not the exact circle.",xp=7050,conf={"name"}}
ns.Q[96246]={n="Blackmaw Pouches",l=60,r=55,fa="Both",d="BlackmawHold",ds={"BlackmawHold"},role="main",s={m=1447,x=42,y=38.9,n="Ekkal"},f={m=1447,x=42,y=38.9,n="Ekkal"},st="Ekkal, Ruins of Eldarath, Azshara (42.0, 38.9)",ft="Ekkal, Ruins of Eldarath, Azshara (42.0, 38.9)",oe="Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara.",ne="Repeatable, after the first Blackmaw Pouches.",rw="Timbermaw Hold +100",req={{"Blackmaw Pouch",1,"From the Blackmaw furbolgs inside Blackmaw Hold"}},rep=true}
