ns.Q[5262]={n="The Truth Comes Crashing Down",nf="La vérité vient du ciel",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving","StratholmeUndead"},role="main",p={5251},s={i=1,n="Head of Balnazzar"},f={m=1423,x=71.6,y=50.1,n="Duke Nicholas Zverenhoff"},st="Head of Balnazzar (drops from Balnazzar)",ft="Duke Nicholas Zverenhoff, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Head of Balnazzar",c=1,ins=false,unk=true,ns=false,t={"Balnazzar"},src={{"Balnazzar",100}}}},oe="Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.",of="Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est.",ne="Hand in The Archivist first, or Balnazzar's head will not start this quest.",xp=17450,sh=false,si="Head of Balnazzar",sid=13250,sih="Dropped by Balnazzar (hand in The Archivist first)"}
ns.Q[5251]={n="The Archivist",nf="L'archiviste",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving","StratholmeUndead"},role="pre",s={m=1423,x=71.6,y=50.1,n="Duke Nicholas Zverenhoff"},f={m=1423,x=71.6,y=50.1,n="Duke Nicholas Zverenhoff"},st="Duke Nicholas Zverenhoff, Light's Hope Chapel, Eastern Plaguelands",ft="Duke Nicholas Zverenhoff, Light's Hope Chapel, Eastern Plaguelands",o={{k="kill",n="Archivist Galford",c=1,ins=false,unk=true,ns=false,t={"Archivist Galford"}},{k="object",n="Scarlet Archive",c=1,ins=false,unk=true,ns=false}},oe="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.",of="Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates.",ne="Kill Archivist Galford in the Scarlet Bastion and burn the archives.",rw="1g 80s",xp=17450,sh=true,conf={"fdj"}}
ns.Q[5212]={n="The Flesh Does Not Lie",nf="La chair ne ment pas",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving","StratholmeUndead"},role="main",s={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},f={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},st="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",ft="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Plagued Flesh Sample",c=20,ins=false,unk=true,ns=false,t={"Ravaged Cadaver","Mangled Cadaver","Plague Ghoul"},src={{"Ravaged Cadaver",80},{"Mangled Cadaver",80},{"Plague Ghoul",80}}}},oe="Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.",of="Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair.",ne="Any undead in Stratholme can drop Plagued Flesh Samples.",rw="1g 80s",xp=14500,sh=true,conf={"fdj"}}
ns.Q[5243]={n="Houses of the Holy",nf="Les demeures du Sacré",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving"},role="main",s={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},f={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},st="Leonid Barthalomew the Revered, Light's Hope Chapel, Eastern Plaguelands",ft="Leonid Barthalomew the Revered, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Stratholme Holy Water",c=5,ins=false,unk=true,ns=false,src={{"Supply Crate",100},{"Stratholme Supply Crate",100}}}},oe="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",of="Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni.",ne="Collect 5 Stratholme Holy Water from the supply crates in the streets; some crates spawn enemies.",rw="1g 80s",ri={"Crown of the Penitent","Band of the Penitent"},rc=true,xp=14500,sh=true,conf={"fdj"}}
ns.Q[5214]={n="The Great Ezra Grimm",nf="Le grand Ezra Grimm",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving"},role="main",s={m=1423,x=70.9,y=48.4,n="Smokey LaRue"},f={m=1423,x=70.9,y=48.4,n="Smokey LaRue"},st="Smokey LaRue, Light's Hope Chapel, Eastern Plaguelands",ft="Smokey LaRue, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Grimm's Premium Tobacco",c=1,ins=false,unk=true,ns=false,t={"Ezra Grimm"},src={{"Ezra Grimm",100}}}},oe="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.",of="Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait.",ne="Newer Classic records call him Ezra Grimm. Clear the smoke shop, touch the tobacco box and kill the shopkeeper.",ri={"Smokey's Lighter"},xp=17450,sh=true,conf={"fdj"}}
ns.Q[5848]={n="Of Love and Family",nf="De l'amour et de la famille",l=60,r=52,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving"},role="main",p={5542,5543,5544,5742,5781,5845,5846},s={m=1422,x=65.6,y=75.4,n="Artist Renfray"},f={m=1423,x=5.1,y=35.5,n="Tirion Fordring"},st="Artist Renfray, Caer Darrow, Western Plaguelands",ft="Tirion Fordring, Eastern Plaguelands",o={{k="item",n="Of Love and Family",c=1,ins=false,unk=true,ns=false,src={{"Unfinished Painting",100}}}},oe="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring.",of="Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.\n\nRapporter le tableau à Tirion Fordring.",ne="Take the painting hidden behind the twin-moons picture in Archivist Galford's room before you burn the archives.",xp=13850,sh=true,conf={"zygor"}}
