ns.Q[5845]={n="Of Lost Honor",nf="De l'honneur perdu",l=58,r=52,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving"},role="pre",p={5781},s={m=1423,x=4.3,y=36.1,n="Tirion Fordring"},f={m=1423,x=5.1,y=35.5,n="Tirion Fordring"},st="Tirion Fordring, Eastern Plaguelands",ft="Tirion Fordring, Eastern Plaguelands",o={{k="item",n="Symbol of Lost Honor",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1423,x=62.5,y=26.8,n="Symbol of Lost Honor"},src={{"Symbol of Lost Honor",100}}}},oe="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.",of="Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie.",xp=6200,sh=true}
ns.Q[5846]={n="Of Love and Family",nf="L'amour et la famille",l=58,r=52,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving"},role="pre",p={5845},s={m=1423,x=4.3,y=36.1,n="Tirion Fordring"},f={m=1422,x=65.8,y=75.4,n="Artist Renfray"},st="Tirion Fordring, Eastern Plaguelands",ft="Artist Renfray",oe="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.",of="Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau.",xp=6200,sh=true}
ns.Q[5122]={n="The Medallion of Faith",nf="Le médaillon de foi",l=60,r=55,fa="Both",d="StratholmeLiving",ds={"StratholmeLiving","StratholmeUndead"},role="main",s={i=1,n="Aurius"},f={i=1,n="Aurius"},st="Aurius, Stratholme",ft="Aurius, Stratholme",o={{k="item",n="Medallion of Faith",c=1,ins=false,unk=true,ns=false,src={{"Malor's Strongbox",100}}}},oe="Retrieve the Medallion of Faith from Malor the Zealous in the Scarlet Bastion and bring it back to Aurius.",of="Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.\n\nS'il vous plaît, <nom>, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme.",ne="Malor's Strongbox in the Scarlet Bastion holds the medallion. Give it to Aurius in the chapel before fighting the Baron.",sh=true}
ns.Q[5282]={n="The Restless Souls",nf="Âmes tourmentées",l=60,r=55,fa="Both",d="StratholmeUndead",ds={"StratholmeLiving","StratholmeUndead"},role="main",p={5281},s={m=1423,x=10.9,y=27.2,n="Egan"},f={m=1423,x=11.3,y=26.6,n="Egan"},st="Egan, Terrordale, Eastern Plaguelands",ft="Egan, Terrordale, Eastern Plaguelands",o={{k="kill",n="Restless Soul",c=15,ins=false,unk=true,ns=false,t={"Restless Soul"}}},oe="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan.",of="Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !\n\nLibérer 15 Esprits sans repos puis retourner auprès d’Egan.",rw="1g 80s",ri={"Testament of Hope"},xp=17450,sh=false}
ns.Q[5263]={n="Above and Beyond",nf="Au-dessus et au-delà",l=60,r=55,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead"},role="main",p={5251,5262},s={m=1423,x=71.6,y=50.1,n="Duke Nicholas Zverenhoff"},f={m=1423,x=71.6,y=50.1,n="Duke Nicholas Zverenhoff"},st="Duke Nicholas Zverenhoff, Light's Hope Chapel, Eastern Plaguelands",ft="Duke Nicholas Zverenhoff, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Head of Baron Rivendare",c=1,ins=false,unk=true,ns=false,t={"Baron Rivendare"},src={{"Baron Rivendare",100}}}},oe="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.",of="S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff.",ne="Then Lord Maxwell Tyrosus and The Argent Hold, in Light's Hope Chapel, give the weapon or shield reward.",xp=18250,sh=true,conf={"fdj"}}
ns.Q[5213]={n="The Active Agent",nf="L'agent actif",l=60,r=55,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead"},role="main",p={5212},s={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},f={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},st="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",ft="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",o={{k="item",n="Scourge Data",c=1,ins=false,unk=true,ns=false,src={{"Scourge Data",100}}}},oe="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.",of="Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink.",ri={"Seal of the Dawn","Rune of the Dawn"},rc=true,xp=6600,sh=true,conf={"fdj"}}
ns.Q[6163]={n="Ramstein",l=60,r=56,fa="Horde",d="StratholmeUndead",ds={"StratholmeUndead"},role="main",p={6133,6042,6022,6135,6136},s={m=1423,x=22.2,y=64.3,n="Nathanos Blightcaller"},f={m=1423,x=22.2,y=63.5,n="Nathanos Blightcaller"},st="Nathanos Blightcaller, Marris Stead, Eastern Plaguelands",ft="Nathanos Blightcaller, Marris Stead, Eastern Plaguelands",o={{k="item",n="Head of Ramstein the Gorger",c=1,ins=false,unk=true,ns=false,t={"Ramstein the Gorger"},src={{"Ramstein the Gorger",100}}}},oe="Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",of="Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos.",rw="1g 80s",ri={"Royal Seal of Alexis","Elemental Circle"},rc=true,xp=9900,sh=true}
ns.Q[6133]={n="The Ranger Lord's Behest",nf="L'ordre du seigneur forestier",l=60,r=54,fa="Horde",d="StratholmeUndead",ds={"StratholmeUndead"},role="pre",s={m=1423,x=22.2,y=64.3,n="Nathanos Blightcaller"},f={m=1423,x=22.2,y=63.5,n="Nathanos Blightcaller"},st="Nathanos Blightcaller, Eastern Plaguelands",ft="Nathanos Blightcaller, Eastern Plaguelands",o={{k="kill",n="Pathstrider",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1423,x=46.3,y=12.5,n="Pathstrider"},t={"Pathstrider"}},{k="kill",n="Ranger",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1423,x=44.6,y=15.8,n="Ranger"},t={"Ranger"}},{k="kill",n="Woodsman",c=8,ins=false,unk=false,ns=false,outer=true,w={m=1423,x=44.9,y=15.7,n="Woodsman"},t={"Woodsman"}},{k="item",n="Quel'Thalas Registry",c=1,ins=false,unk=false,ns=false,outer=true,w={m=1423,x=45.3,y=12.7,n="Quel'Thalas Registry"},src={{"Quel'Thalas Registry",100}}}},oe="Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.",of="Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.\n\nTuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons.",xp=6600,sh=true}
