ns.Q[5125]={n="Aurius' Reckoning",nf="L'estimation d'Aurius",l=60,r=55,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead"},role="main",p={5122},s={i=1,n="Aurius"},f={i=1,n="Aurius"},st="Aurius, Stratholme",ft="Aurius, Stratholme",oe="Give Aurius the Medallion of Faith; he joins the fight against Baron Rivendare. Claim his reward after the battle.",of="<nom>, je me meurs… mais mon âme est sauve, et pour cela je vous dois plus que les mots peuvent exprimer. Je vous en prie, prenez ceci… et continuez le combat, brave <classe> !",ne="Give Aurius the Medallion of Faith before the Baron fight; speak to him after Baron Rivendare dies.",ri={"Will of the Martyr","Blood of the Martyr"},rc=true,xp=21900,sh=true}
