ns.Q[5463]={n="Menethil's Gift",nf="Le cadeau de Menethil",l=60,r=57,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead","Scholomance"},role="main",p={5382,5515,5384,5461,5462},s={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},f={i=1,n="Menethil's Gift"},st="Leonid Barthalomew the Revered, Light's Hope Chapel, Eastern Plaguelands",ft="Menethil's Gift, Stratholme",o={{k="item",n="Keepsake of Remembrance",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1417,x=17.9,y=69.4,n="Keepsake of Remembrance"},src={{"Keepsake of Remembrance",100}}}},oe="Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.",of="Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie.",ne="After Baron Rivendare dies, use the glowing rune on the floor of his room, then take the follow-up back to Leonid.",xp=14500,sh=false,conf={"fdj"}}
ns.Q[5382]={n="Doctor Theolen Krastinov, the Butcher",nf="Docteur Theolen Krastinov, le boucher",l=60,r=55,fa="Both",d="StratholmeUndead",od="Scholomance",ds={"StratholmeUndead","Scholomance"},role="pre",s={m=1422,x=70.2,y=73.8,n="Eva Sarkhoff"},f={m=1422,x=70.2,y=73.7,n="Eva Sarkhoff"},st="Eva Sarkhoff, Caer Darrow, Western Plaguelands",ft="Eva Sarkhoff, Caer Darrow, Western Plaguelands",o={{k="kill",n="Doctor Theolen Krastinov",c=1,ins=false,unk=true,ns=false,t={"Doctor Theolen Krastinov"}},{k="object",n="Remains of Eva Sarkhoff",c=1,ins=false,unk=true,ns=false},{k="object",n="Remains of Lucien Sarkhoff",c=1,ins=false,unk=true,ns=false}},oe="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.",of="Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie.",xp=15700,sh=true}
ns.Q[5515]={n="Krastinov's Bag of Horrors",nf="Sac des horreurs de Krastinov",l=60,r=55,fa="Both",d="StratholmeUndead",od="Scholomance",ds={"StratholmeUndead","Scholomance"},role="pre",p={5382},s={m=1422,x=70.2,y=73.8,n="Eva Sarkhoff"},f={m=1422,x=70.2,y=73.7,n="Eva Sarkhoff"},st="Eva Sarkhoff, Caer Darrow, Western Plaguelands",ft="Eva Sarkhoff, Caer Darrow, Western Plaguelands",o={{k="item",n="Krastinov's Bag of Horrors",c=1,ins=false,unk=true,ns=false,t={"Jandice Barov"},src={{"Jandice Barov",100}}}},oe="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",of="Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff.",ne="The bag drops from Jandice Barov.",xp=15700,sh=true}
ns.Q[5384]={n="Kirtonos the Herald",nf="Kirtonos le héraut",l=60,r=55,fa="Both",d="StratholmeUndead",od="Scholomance",ds={"StratholmeUndead","Scholomance"},role="pre",p={5515},s={m=1422,x=70.2,y=73.8,n="Eva Sarkhoff"},f={m=1422,x=70.2,y=73.7,n="Eva Sarkhoff"},st="Eva Sarkhoff, Caer Darrow, Western Plaguelands",ft="Eva Sarkhoff, Caer Darrow, Western Plaguelands",o={{k="kill",n="Kirtonos the Herald",c=1,ins=false,unk=true,ns=false,t={"Kirtonos the Herald"}}},oe="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.",of="Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.\n\nCombattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff.",ne="Use the Blood of Innocents at the brazier on the Scholomance porch. Rewards the Spectral Essence.",ri={"Penelope's Rose","Mirah's Song"},rc=true,xp=19700,sh=false}
ns.Q[5461]={n="The Human, Ras Frostwhisper",nf="L'humain, Ras Murmegivre",l=60,r=57,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead","Scholomance"},role="pre",p={5384},s={m=1422,x=70.4,y=74,n="Magistrate Marduke"},f={m=1422,x=70.6,y=74.1,n="Magistrate Marduke"},st="Magistrate Marduke, Western Plaguelands",ft="Magistrate Marduke, Western Plaguelands",o={{k="item",n="Keepsake of Remembrance",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1417,x=17.9,y=69.4,n="Keepsake of Remembrance"},src={{"Keepsake of Remembrance",100}}}},oe="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.",of="Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke.",xp=6600,sh=true}
ns.Q[5462]={n="The Dying, Ras Frostwhisper",nf="Le moribond, Ras Murmegivre",l=60,r=57,fa="Both",d="StratholmeUndead",ds={"StratholmeUndead","Scholomance"},role="pre",p={5461},s={m=1422,x=70.4,y=74,n="Magistrate Marduke"},f={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},st="Magistrate Marduke, Western Plaguelands",ft="Leonid Barthalomew the Revered, Eastern Plaguelands",o={{k="item",n="Keepsake of Remembrance",c=1,ins=false,unk=false,ns=false,outer=false,w={m=1417,x=17.9,y=69.4,n="Keepsake of Remembrance"},src={{"Keepsake of Remembrance",100}}}},oe="Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.",of="Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert.",xp=4950,sh=false}
ns.Q[5466]={n="The Lich, Ras Frostwhisper",nf="La Liche, Ras Murmegivre",l=60,r=57,fa="Both",d="Scholomance",ds={"Scholomance"},role="main",p={5382,5515,5384,5461,5462,5463,5464,5465},s={m=1422,x=70.4,y=74,n="Magistrate Marduke"},f={m=1422,x=70.6,y=74.1,n="Magistrate Marduke"},st="Magistrate Marduke, Caer Darrow, Western Plaguelands",ft="Magistrate Marduke, Caer Darrow, Western Plaguelands",o={{k="item",n="Human Head of Ras Frostwhisper",c=1,ins=false,unk=true,ns=false,t={"Ras Frostwhisper"},src={{"Ras Frostwhisper",100}}}},oe="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",of="Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke.",ne="Use the Soulbound Keepsake on Ras Frostwhisper to make him human, then kill him and bring back his human head.",ri={"Warblade of Caer Darrow","Crown of Caer Darrow","Darrowspike","Darrowshire Strongguard"},rc=true,xp=23650,sh=false}
ns.Q[5464]={n="Menethil's Gift",nf="Le cadeau de Menethil",l=60,r=57,fa="Both",d="Scholomance",ds={"Scholomance"},role="pre",p={5463},s={i=1,n="Menethil's Gift"},f={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},st="Menethil's Gift",ft="Leonid Barthalomew the Revered, Eastern Plaguelands",o={{k="item",n="Soulbound Keepsake",c=1,ins=false,unk=false,ns=true}},oe="Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.",of="Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est.",xp=8300,sh=false}
ns.Q[5465]={n="Soulbound Keepsake",nf="Souvenir lié",l=60,r=57,fa="Both",d="Scholomance",ds={"Scholomance"},role="pre",p={5464},s={m=1423,x=71.9,y=48.3,n="Leonid Barthalomew the Revered"},f={m=1422,x=70.6,y=74.1,n="Magistrate Marduke"},st="Leonid Barthalomew the Revered, Eastern Plaguelands",ft="Magistrate Marduke, Western Plaguelands",o={{k="item",n="Soulbound Keepsake",c=1,ins=false,unk=false,ns=true}},oe="Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.",of="Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié.",xp=4950,sh=false,conf={"fdj"}}
ns.Q[5341]={n="Barov Family Fortune",nf="Fortune de la famille Barov",l=60,r=52,fa="Horde",d="Scholomance",ds={"Scholomance"},role="main",s={m=1420,x=83,y=71.4,n="Alexi Barov"},f={m=1420,x=83,y=71.6,n="Alexi Barov"},st="Alexi Barov, The Bulwark, Tirisfal Glades",ft="Alexi Barov, The Bulwark, Tirisfal Glades",o={{k="item",n="The Deed to Brill",c=1,ins=false,unk=true,ns=false,src={{"The Deed to Brill",100}}},{k="item",n="The Deed to Caer Darrow",c=1,ins=false,unk=true,ns=false,src={{"The Deed to Caer Darrow",100}}},{k="item",n="The Deed to Southshore",c=1,ins=false,unk=true,ns=false,src={{"The Deed to Southshore",100}}},{k="item",n="The Deed to Tarren Mill",c=1,ins=false,unk=true,ns=false,src={{"The Deed to Tarren Mill",100}}}},oe="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",of="S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d’Austrivage. Revenir auprès d’Alexi Barov quand la tâche est accomplie.",ne="The four deeds: Southshore in the first large chamber, Tarren Mill before the hatchlings, Brill by Ras Frostwhisper, Caer Darrow by Lord Alexei Barov. The follow-up The Last Barov sends you to kill the rival brother.",rw="1g 80s",xp=15700,sh=true}
ns.Q[4771]={n="Dawn's Gambit",nf="Le gambit de l'aube",l=60,r=57,fa="Both",d="Scholomance",ds={"Scholomance"},role="main",p={4726,4808,4809,4810,4734,4735,5522,5531},s={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},f={m=1423,x=71.7,y=49.9,n="Betina Bigglezink"},st="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",ft="Betina Bigglezink, Light's Hope Chapel, Eastern Plaguelands",o={{k="kill",n="Vectus",c=1,ins=false,unk=true,ns=false,t={"Vectus"}},{k="event",ins=false,unk=false,ns=true}},oe="Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.",of="Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink.",ne="Use Dawn's Gambit in the Viewing Room and defeat Vectus.",rw="2g 70s",ri={"Windreaper","Dancing Sliver"},rc=true,xp=23650,sh=false,conf={"fdj"}}
